  },
  CollectionHall_121154_Title = {Text = "Paradies"},
  CollectionHall_121341_Desc = {
    Text = "<Title:Einführung>\nDie “Prinzessin“, die die Verantwortung für die Geburt des “Heiligen Kindes“ angenommen hat, ist heute die “Göttliche Mutter“, eine entscheidende Figur innerhalb der Seefahrer-Gemeinschaft.\nSie war einst eine Dame, die der Freiheit entgegenlief, und begab sich, genau wie Murphy, die in Misaq aufgezeichnet ist, auf die Flucht mit der Sonanir.\nDoch in einer Welt ohne Schutzherren brach das Schicksal den edlen Hals des jungen Schwans.\nDie verdrehte Blutlinie umschlang sie ohne Widerstand und ohne Erbarmen, selbst wenn sie ihren Körper sterben ließ, konnte sie dem nicht entkommen. Sie hielt sich tapfer und sprach immer wieder: “Ich bin die edle Göttliche Mutter“, was nur eine Selbstsuggestion und Überzeugung war.\nSie konnte nur gehorchen, nur gehorchen. Gehorsam gegenüber den trügerischen Orakeln, gehorchen dem absurden Schicksal und fand schließlich aus dem unendlichen Bitteren mühsam einen Hauch der süßen Illusion."
  },
  CollectionHall_121341_LockTip = {
    Text = "Nach Erweckung von “Wahn·Murphy“ freigeschaltet"
  },
  CollectionHall_121341_Title = {
    Text = "Murphy: Fauxgeboren"
  },
  CollectionHall_121381_Desc = {
    Text = "Du hast eine tausend Eicheln gegen eine Geschichte aus einer anderen Welt eingetauscht. \n Eine Geschichte über Helden und Dämonen, Wachsamkeit und Durchhaltevermögen. \n Eine Geschichte über Unvermögen und Wehmut, alte Freunde und neue Freunde. \n Eine Geschichte, die einmal hier war."
  },
  CollectionHall_121381_LockTip = {
    Text = "Abgeschlossen der multidimensionalen Verbindung “Ich bin dran“"
  },
  CollectionHall_121381_Title = {
    Text = "Echos der Wankard-Taverne"
  },
  CollectionHall_121382_Desc = {
    Text = "Viele, viele Jahre später hatten er und er schließlich ein Lied, das gesungen wurde. \nÜber die Erlösung des Wiederbelebens, über die Zwillingsseelen."
  },
  CollectionHall_121382_LockTip = {
    Text = "Vollende “Abweichende Traumwelt, Jenseits des Horizonts·unter“"
  },
  CollectionHall_121382_Title = {
    Text = "Gedicht des flügellosen Vogels"
  },
  CollectionHall_121383_Desc = {
    Text = "Der Junge hat für alles Vergängliche den Preis gezahlt, der eingefordert wurde. \n Nun bleibt nur die stille Macht an seiner Seite. \n Der König wird schlafen, und er begrüßt das Ende der Welt in seinen Träumen."
  },
  CollectionHall_121383_LockTip = {
    Text = "Abgeschlossen das Wandern „Tag der Krönung“"
  },
  CollectionHall_121383_Title = {
    Text = "Königreich der grenzenlosen Einsamkeit"
  },
  CollectionHall_121384_Desc = {
    Text = "Sie umgeben dich, sie bewundern dich, sie begleiten dich. \n Sie setzen die Segel zum Schöpfergott."
  },
  CollectionHall_121384_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-11 freischalten"
  },
  CollectionHall_121384_Title = {
    Text = "Setze Segel zum Schöpfergott"
  },
  CollectionHall_121385_Desc = {
    Text = "Das sind Flügel, die aus Zerschlagung wiedergeboren wurden, Flügel, die Freiheit durch Opfergabe erkaufen. \n Die Prophezeiung des Schicksals hat sich erfüllt, er schwor in seiner Reue, dass die Blutschuld mit Blut beglichen werden muss."
  },
  CollectionHall_121385_LockTip = {
    Text = "Vollende “Jenseits des Horizonts·unter“ in der Abweichenden Traumwelt"
  },
  CollectionHall_121385_Title = {
    Text = "Wenn der Sturm aufzieht"
  },
  CollectionHall_121386_Desc = {
    Text = "Im Anfang des absurden und chaotischen Traums war Er dazu bestimmt, seinem Schicksal gegenüberzutreten. \n Doch Er hat bereits zu viel erlebt und zu viel definiert. \n Er hat mit der größtmöglichen Vernunft, die die Menschheit bewahren kann, beschlossen, auf seinen Ursprung zu blicken, das höchste Wesen."
  },
  CollectionHall_121386_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-11 zur Freischaltung"
  },
  CollectionHall_121386_Title = {
    Text = "Ursprünglicher Kampf des Schicksals"
  },
  CollectionHall_121387_Desc = {
    Text = "Erhalten, verlieren, durchtrennen, Opfergabe. \n Der Held hat den gesamten Preis bezahlt, das Recht, die Schätze zu beschützen, ist seine Belohnung."
  },
  CollectionHall_121387_LockTip = {
    Text = "Abgeschlossen Ermittlungsoperation 9-13 freigeschaltet"
  },
  CollectionHall_121387_Title = {
    Text = "Schülerloses Auge"
  },
  CollectionHall_121388_Desc = {
    Text = "Er setzte sich die Krone auf, er legte sich die Fesseln an. \n Das ist die flüchtige, illusorische Wärme, das ist der zum Untergang bestimmte Glanz der vergangenen Tage."
  },
  CollectionHall_121388_LockTip = {
    Text = "Abgeschlossen das Wandern „Tag der Krönung“"
  },
  CollectionHall_121388_Title = {
    Text = "Einsame Reise des jungen Königs"
  },
  CollectionHall_121389_Desc = {
    Text = "Obwohl die Situation gegen dich spricht, hebt sich der Mundwinkel bereits leicht. \n„Mein Zug, Karten ziehen!“ \nEgal ob im Wankard-Gasthaus oder in Misaq, \nwer die Schadensfähigkeit der Unterstützung unterschätzt, wird schwer treffen! Ignatius!"
  },
  CollectionHall_121389_LockTip = {
    Text = "Abgeschlossen der multidimensionalen Verbindung “Ich bin dran“"
  },
  CollectionHall_121389_Title = {
    Text = "Mein umgekehrter Moment!"
  },
  CollectionHall_121390_Desc = {
    Text = "Eine vollständige Legende kann nicht ohne die Verwandlung von Feinden in Freunde auskommen."
  },
  CollectionHall_121390_LockTip = {
    Text = "Abgeschlossen Ermittlungsaktion · Schwierig 9-10 entsperrt"
  },
  CollectionHall_121390_Title = {
    Text = "Feind, Freund"
  },
  CollectionHall_121391_Desc = {
    Text = "Von nun an wirst du als Hüter des Geheimnisses mit den vielen Schülern und Lehrern von Missaga zusammen sein"
  },
  CollectionHall_121391_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz·Schwierig 9-11 zur Freischaltung"
  },
  CollectionHall_121392_Desc = {
    Text = "Wir sind vielleicht ein flüchtiger Moment in der Ewigkeit, ein Kieselstein im wilden Strom. \n Doch die gewöhnliche Welt ist unser kostbares Ewiges, denn egal wie verrückt und chaotisch die Welt auch sein mag – \n die Würde des Menschen wird auf dem Glanz der Vernunft gegründet."
  },
  CollectionHall_121392_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-11 zur Freischaltung"
  },
  CollectionHall_121392_Title = {
    Text = "Loblied der Ewigkeit"
  },
  CollectionHall_121393_Desc = {
    Text = "Die Helden stürzten sich in das Märchen, jedes Märchen ist gleich, Tiere, Teufel, Feen und das unbekannte Jenseits. \n Über die flüchtige Freiheit und die falschen Sehnsüchte hinweg verbirgt das Ende des Märchens ein ihm aufgezwungenes falsches Herz."
  },
  CollectionHall_121393_LockTip = {
    Text = "Vollende “Abweichende Traumwelt, Jenseits des Horizonts·unter“"
  },
  CollectionHall_121393_Title = {
    Text = "Flug in die Sternenstraße"
  },
  CollectionHall_121394_Desc = {
    Text = "Hier ist das Wankard-Gasthaus, das sich im Raum-Zeit-Riss einer anderen Welt befindet. \n Die Portale, die verschiedene Universen verbinden, blitzen mit überwältigendem Sternenlicht und heißen dich willkommen. \n Moment mal ... was hast du hier, Schutzherr, zu suchen?"
  },
  CollectionHall_121394_LockTip = {
    Text = "Abgeschlossen der multidimensionalen Verbindung “Ich bin dran“"
  },
  CollectionHall_121394_Title = {
    Text = "Willkommen im Wankard-Gasthaus!"
  },
  CollectionHall_121395_Desc = {
    Text = "Die Klinge von Misaq wird dir den Sieg in diesem Duell bringen.\nDie Bindung zwischen dir und deinem Partner ist unzerstörbar.\nSelbst wenn ihr eines Tages in verschiedenen Universen seid, wird sich daran nichts ändern."
  },
  CollectionHall_121395_LockTip = {
    Text = "Abgeschlossen der multidimensionalen Verbindung “Ich bin dran“"
  },
  CollectionHall_121395_Title = {
    Text = "Mythags Klinge!"
  },
  CollectionHall_121396_Desc = {
    Text = "„Hast du das tägliche Training nicht gemacht? Lass uns lieber eine Runde Wankard-Karten spielen!“\n„Hast du die Fusionskatastrophe Sperrzone nicht gespielt? Lass uns lieber eine Runde Wankard-Karten spielen!“\n„Das ist ein Phasenduell, keine Wankard-Karten! Ich werde dir tausend Eicheln sammeln, um sie dir zu zeigen!“"
  },
  CollectionHall_121396_LockTip = {
    Text = "Abgeschlossen der multidimensionalen Verbindung “Ich bin dran“"
  },
  CollectionHall_121396_Title = {
    Text = "Lass uns Wankard-Karten spielen!"
  },
  CollectionHall_121397_Desc = {
    Text = "Rufe meinen Namen, bevor die vergessene Dämmerung kommt."
  },
  CollectionHall_121397_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz·Schwierig 9-11 zur Freischaltung"
  },
  CollectionHall_121397_Title = {
    Text = "aus dem Vergessen@2"
  },
  CollectionHall_121398_Desc = {
    Text = "„Komm und schließe einen Vertrag mit mir ab, um Kartenspielmeister zu werden!“\n Diese aus einer anderen Welt stammende Drachenmädchen hat dir eine leidenschaftliche und rätselhafte Einladung ausgesprochen.\n Um diesen kleinen Vorfall im Phasenraum schnellstmöglich zu normalisieren, hast du keine andere Wahl."
  },
  CollectionHall_121398_LockTip = {
    Text = "Abgeschlossen der multidimensionalen Verbindung “Ich bin dran“"
  },
  CollectionHall_121398_Title = {
    Text = "Wirtin, Ignatius!"
  },
  CollectionHall_121399_Desc = {
    Text = "Später werden die Nachfolger unter der schweren Gabe eine solche Fußnote finden. \n Der einzige, der der Heldentat entkommen konnte, wurde zum Helden, und das Kind, das die Freundschaft schätzt, hat nur noch einen einzigen Freund."
  },
  CollectionHall_121399_LockTip = {
    Text = "Abgeschlossen das Wandern „Tag der Krönung“"
  },
  CollectionHall_121399_Title = {
    Text = "Ich werde einsam gehen"
  },
  CollectionHall_121400_Desc = {
    Text = "Löse dich von dem Herrn, stelle dich dem Herrn, widerspreche dem Herrn.\nDeine Geschichte ist unbekannt, dein Gedächtnis wird ewig bestehen."
  },
  CollectionHall_121400_LockTip = {
    Text = "Abgeschlossen Ermittlungsoperation 9-13 freigeschaltet"
  },
  CollectionHall_121400_Title = {
    Text = "Herr der uralten törichten Schöpfung"
  },
  CollectionHall_121401_Desc = {
    Text = [[
Nichts hat mehr Bedeutung, deshalb stehst du hier. 
 Alles, was einmal war, ist die gesamte Bedeutung, die du definiert hast, also stehst du hier.]]
  },
  CollectionHall_121401_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-13 freigeschaltet"
  },
  CollectionHall_121401_Title = {
    Text = "Existenzialismus"
  },
  CollectionHall_121402_Desc = {
    Text = "Der Weg zu ihnen, der Weg von ihnen weg. \n Alles wird sich bald trennen, alles wird bald enden, alles wird bald beginnen. \n Die Gestalt vor der Tür beginnt nun das lange Warten, auf dass der Silberschlüssel dich auf deinem Rückweg leitet."
  },
  CollectionHall_121402_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-13 freigeschaltet"
  },
  CollectionHall_121402_Title = {
    Text = "Der Pfad zu ihnen"
  },
  CollectionHall_121403_Desc = {
    Text = "Ihre Möglichkeiten verlaufen in Linien, Trennung, Zusammenziehung, Zerfall. \n Bis der einzige Erlöser kommt, bis wir schließlich in das einzige Ende eintreten."
  },
  CollectionHall_121403_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz·Schwierig 9-10 wurde entsperrt"
  },
  CollectionHall_121403_Title = {
    Text = "Das einzige Ende"
  },
  CollectionHall_121404_Desc = {
    Text = "Der junge König hat diesen Deal akzeptiert. \n Er sagte: Mein Reich wird in Sicherheit sein."
  },
  CollectionHall_121404_LockTip = {
    Text = "Abgeschlossen das Wandern „Tag der Krönung“"
  },
  CollectionHall_121404_Title = {Text = "Krönung"},
  CollectionHall_121405_Desc = {
    Text = "In dieser zerbrochenen Raum-Zeit-Riss stand einst das legendäre Wankard-Gasthaus. \n Es verband einst verschiedene Universen durch Portale, funkelte einst mit dem Glanz unzähliger Sterne und begrüßte einst jeden Kartenspielmeister. \n Und du bist der Beweis für all diese Existenz."
  },
  CollectionHall_121405_LockTip = {
    Text = "Abgeschlossen der multidimensionalen Verbindung “Ich bin dran“"
  },
  CollectionHall_121405_Title = {
    Text = "Auf Wiedersehen, Kartenspielmeister!"
  },
  CollectionHall_121406_Desc = {
    Text = "Der Herr sah dich an, du durchbrachst die Augen des Herrn."
  },
  CollectionHall_121406_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-13 freigeschaltet"
  },
  CollectionHall_121406_Title = {Text = "Endreise"},
  CollectionHall_121407_Desc = {
    Text = "Krieger, Rächer, Sklave, Herr, Händler. \n Gleiche Position? Unterschiedliche Positionen? Gleiche Position."
  },
  CollectionHall_121407_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-11 zur Freischaltung"
  },
  CollectionHall_121407_Title = {
    Text = "Vielfältiges Kriegslied"
  },
  CollectionHall_121408_Desc = {
    Text = "Du weißt, dass du nicht für etwas Großes kämpfst.\nUm dem Unterricht zu entkommen, um Hausaufgaben, um Desserts, um Freunde, um den Kamin, um die Zeit totzuschlagen.\nDu bist nur ein gewöhnlicher Mensch, der für die alltäglichen Dinge stirbt."
  },
  CollectionHall_121408_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz·Schwierig 9-11 zur Freischaltung"
  },
  CollectionHall_121408_Title = {
    Text = "Für die, die im Alltag sterben"
  },
  CollectionHall_121409_Desc = {
    Text = "Tiere, alle höheren Tiere, sind unweigerlich von sozialen Verhaltensweisen kontrolliert. \n Doch sie selbst stürzt sich in den Tod, um die Wahrheit nach ihrem Wunsch zu dekonstruieren. \n Ein wahnsinniger, einzigartiger Genius, sie zieht lieber selbst die Zerstörung herbei und schenkt allen das Entkommen aus dem Gift namens Hoffnung."
  },
  CollectionHall_121409_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-13 freigeschaltet"
  },
  CollectionHall_121409_Title = {
    Text = "Dekonstruktion von Gemeinschaftsverhalten"
  },
  CollectionHall_121410_Desc = {
    Text = "Er sendet aus den Höhen unaufhörlich bitteres Wasser, das sich sammelt, sammelt. \n Schließlich wird es zu dem Fluss, der vor unserem vereinten Fleisch und Blut liegt und der dazu bestimmt ist, zurückverfolgt zu werden."
  },
  CollectionHall_121410_LockTip = {
    Text = "Vollende “Jenseits des Horizonts·unter“ in der Abweichenden Traumwelt"
  },
  CollectionHall_121410_Title = {
    Text = "Bitterer Fluss"
  },
  CollectionHall_121411_Desc = {
    Text = "Sie verabschieden sich mit der Erwartung des Wiedersehens.\nDenn es ist ein sehr geschätzter Mensch, denn es ist der Tod eines sehr geschätzten Menschen, der nicht vorherbestimmt ist."
  },
  CollectionHall_121411_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-11 zur Freischaltung"
  },
  CollectionHall_121411_Title = {
    Text = "Der Tod eines Kostbaren"
  },
  CollectionHall_121412_Desc = {
    Text = [[
Mach eine Pause und atme durch. 
 Selbst wenn das Thema das Ende der Welt ist, hat nicht jeder die Gelegenheit, gleichzeitig drei so bedeutende Mentoren zu begegnen.]]
  },
  CollectionHall_121412_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-13 freigeschaltet"
  },
  CollectionHall_121412_Title = {
    Text = "Zwischenspiel"
  },
  CollectionHall_121413_Desc = {
    Text = "Die Geschichte von tausend Eicheln muss mit der ersten beginnen. \n In einem Phasenduell, jedes Mal wenn du eine Karte spielst, \n zieht ein Hauch von goldenem Erinnerungslicht über Ignatius' Augen."
  },
  CollectionHall_121413_LockTip = {
    Text = "Abgeschlossen der multidimensionalen Verbindung“Ich bin dran“"
  },
  CollectionHall_121413_Title = {
    Text = "Unbegrenzte Nachfüllung!"
  },
  CollectionHall_121414_Desc = {
    Text = "Wahnsinn, die Vorboten der Zerstörung, das ist die grundlegende Logik einer geordneten Welt. \n Wird Er zerstören, wird die Welt zerstört werden? \n Niemand weiß es. \n Doch vor dem Schöpfergott nährt der Wahnsinn Sein und die Wiedergeburt der Welt."
  },
  CollectionHall_121414_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-11 freischalten"
  },
  CollectionHall_121414_Title = {
    Text = "Wahnsinnsfuge"
  },
  CollectionHall_121415_Desc = {
    Text = "Was ist das Unvernünftigste auf der Welt? \n Er hat kein Ziel, keine Feindschaften, unterscheidet nicht zwischen Gut und Böse. \n Er möchte einfach alles, was in seinem Traum entstanden ist, zu Staub zermahlen, wenn er aufwacht."
  },
  CollectionHall_121415_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-13 freigeschaltet"
  },
  CollectionHall_121415_Title = {
    Text = "Zerkleinertes Pulver"
  },
  CollectionHall_121416_Desc = {
    Text = [[
Als dieses einzigartige Fragment ist es einfach, ein Gott zu werden. 
 Was ist also der Preis?]]
  },
  CollectionHall_121416_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz 9-13 freigeschaltet"
  },
  CollectionHall_121416_Title = {
    Text = "Gott werden"
  },
  CollectionHall_121417_Desc = {
    Text = "In der langen Geschichte der menschlichen Zivilisation haben wir viele Dinge erschaffen. \n Über Materie, über Geist, über Existenz, Liebe, Rauch und Konflikte. \n Doch das ist nur das unbedeutende Geräusch im Traum des Schöpfers und eine vernachlässigte Fiktion."
  },
  CollectionHall_121417_LockTip = {
    Text = "Abgeschlossen Ermittlungsoperation 9-13 freigeschaltet"
  },
  CollectionHall_121417_Title = {
    Text = "Fiktionale Sammlung"
  },
  CollectionHall_121418_Desc = {
    Text = "Der feigste Schutzherr von Misaq ist in riesigem Glück gestorben."
  },
  CollectionHall_121418_LockTip = {
    Text = "Abgeschlossen Ermittlungseinsatz·Schwierig 9-11 zur Freischaltung"
  },
  CollectionHall_121418_Title = {
    Text = "Der entschlossene Held zur Flucht"
  },
  CollectionHall_121898_LockTip = {
    Text = "Kapitel 4-0 der Ermittlungsoperation Sternenkapitel wurde entsperrt"
  },
  CollectionHall_121898_Title = {
    Text = "Ewige Täuschungspilgerfahrt"
  },
  CollectionHall_121901_LockTip = {
    Text = "Kapitel 4-16 der Ermittlungsoperation Sternekapitel wurde freigeschaltet"
  },
  CollectionHall_121901_Title = {
    Text = "Göttliche Geburt - Sieben Tage"
  },
  CollectionHall_122565_LockTip = {
    Text = "Schließe einen beliebigen Abschnitt des zeitbegrenzten Events „Im Nebel verborgene Sakramente: Das verlorene Selbst“ ab"
  },
  CollectionHall_122565_Title = {
