  CollectionHall_124141_Desc = {
    Text = "Sie und sie teilen ihre Hingabe, während er und er ihre Rebellion und Loyalität haben. \n Sie webt eine große Lüge, und er, ihm, sie und sie spielen mit ihr mit. \n Zuhause bildet jeder eine süße und untrennbare Familie."
  },
