  CollectionHall_133769_Title = {Text = "Untergang"},
  CollectionHall_133770_Desc = {
    Text = "Willkommen, Fahrgäste!\nDas Jahreswechsel Fest naht! In dieser freudvollen Jahreszeit der Wiedersehen und Neuanfänge übermittelt unsere gesamte Besatzung die herzlichsten Wünsche an alle müden Reisenden auf dem langen Weg nach Hause:\n\nWir wünschen euch ein frohes Jahreswechsel Fest, fröhliche Familientreffen, eine schnelle Fahrt und das Allerbeste! <(￣︶￣)↗[GO!]"
  },
  CollectionHall_133770_LockTip = {
    Text = "Abschluss des Sondereinsatzprotokolls „Der Zug zum Qisui-Festival\""
  },
  CollectionHall_133770_Title = {
    Text = "Geschäftig · Himmelsschiene"
  },
  CollectionHall_133771_Desc = {
    Text = "Achtung, liebe Fahrgäste, wir bedauern Ihnen mitteilen zu müssen, dass dieser Expresszug aufgrund der Stimmung des Schaffners hier einen außerplanmäßigen Halt einlegen wird. Die genaue Abfahrtszeit wird über die Lautsprecheranlage bekanntgegeben, sobald das gegenseitige Abschlachten beendet ist.\nWährend dieses Aufenthalts bleiben Klimaanlage, Beleuchtung und Toiletten vollständig in Betrieb. Bitte nutzen Sie diese nach eigenem Ermessen entsprechend Ihrem Schlachtbedarf, um zu vermeiden, dass Sie sich nicht in Gefahr befinden.\nSchließlich ist es die einzige Pflicht des fröhlichen Expresszuges, allen unseren Fahrgästen Freude zu bringen! ~(￣▽￣~)(~￣▽￣)~"
  },
  CollectionHall_133771_LockTip = {
    Text = "Abschluss des Sondereinsatzprotokolls „Der Zug zum Qisui-Festival\""
  },
  CollectionHall_133771_Title = {Text = "Notbremse!"},
  CollectionHall_133772_Desc = {
    Text = "Achtung bitte: Der nächste Halt ist das Drachenland. Reisenden, die im Drachenland aussteigen möchten, wird dringend empfohlen, ihre Gesangstechniken für <Italic:Was für eine wunderschöne Jasminsblüte> aufzufrischen.\nDenn... nun ja, ihr steigt sowieso nie aus diesem Zug aus~ φ(≧ω≦*)♪"
  },
