  CollectionHall_142154_Title = {Text = "Stadt"},
  CollectionHall_142155_Desc = {
    Text = "Wenn man von unbegreiflichen, unkenntlichen und widerlichen Missgestalten bedrängt wird, ist ein defensiver Angriff der Instinkt jedes Lebewesens.\nDaher kann dies nicht als Sünde gewertet werden."
  },
  CollectionHall_142155_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen: Schwierig"
  },
  CollectionHall_142155_Title = {
    Text = "Schuldlose Grausamkeit"
  },
  CollectionHall_142156_Desc = {
    Text = "„Kannst du meine Stimme hören? Selbst wenn meine Gestalt im Wind schmilzt.\"\nAus dem Wind erklingt ein ferner Ruf — eine Stimme, die über weite Zeit hinweg, aus einer weiten und kalten Winternacht, vom jenseitigen Ufer der Vergessenheit herüberdringt und sucht."
  },
  CollectionHall_142156_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen"
  },
  CollectionHall_142156_Title = {
    Text = "忘却の彼方"
  },
  CollectionHall_142157_Desc = {
    Text = "Erinnerungen blitzen auf und überlagern sich, das Ende bleibt ungewiss zwischen Wahrheit und Lüge.\nDoch ist das wirklich von Bedeutung?\nSchließlich beginnen nicht alle Geschichten mit Liebe — aber alle enden mit dem Tod."
  },
  CollectionHall_142157_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen"
  },
  CollectionHall_142157_Title = {
    Text = "Vierfache Erinnerung"
  },
  CollectionHall_142158_Desc = {
    Text = "Wenn du eines Tages, genau wie ich, in einen Anblick aus Caro, Fäulnis und Verwesung versinkst,\ndann wirst du gewiss verstehen —\ndass der Moment, in dem ihre zierlichen Fingerspitzen die meinen berühren, ein unschätzbares Wunder dieser Welt ist."
  },
  CollectionHall_142158_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen"
  },
  CollectionHall_142158_Title = {Text = "Wunder"},
  CollectionHall_142159_Desc = {
    Text = "Bist auch du des gewöhnlichen, sich wiederholenden, eintönigen, tagtäglichen Lebens überdrüssig?\nDann lass etwas Neues zu — eine andere Welt öffnet ihren Rachen weit und lädt dich willkommen ein."
  },
  CollectionHall_142159_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen"
  },
  CollectionHall_142159_Title = {
    Text = "Blutgefilde"
  },
  CollectionHall_142160_Desc = {
    Text = [[
Liebe ist Erhabenheit, Liebe ist Gier; Liebe ist Segen, Liebe ist Fluch.
Liebe entsteht mit dem Wasser und wird mit dem Wasser vergehen.
Doch die Regenzeit kehrt nicht wieder.]]
  },
  CollectionHall_142160_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen: Schwierig"
  },
  CollectionHall_142160_Title = {Text = "Regenzeit"},
  CollectionHall_142161_Desc = {
    Text = "Alles Leben wird in Unwissenheit geboren, zieht Nahrung aus allem, was existiert, verändert die Umwelt, plündert Ressourcen und spendet sich selbst.\nDas ist die unausweichliche Erbsünde."
  },
  CollectionHall_142161_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen"
  },
  CollectionHall_142161_Title = {Text = "Ursünde"},
  CollectionHall_142162_Desc = {
    Text = "Es gibt eine Pflanze namens Pusteblume, die ihre Samen im Wind davontragen lässt.\nDie flauschigen Samen wandern mit dem Wind, weit fort von ihrer Heimat.\nGanz allein — wann wird sie wohl ihr Ziel bestimmen?\nDann nämlich, wenn in der Wüste ein einziger Mensch diese Pusteblume liebt."
  },
  CollectionHall_142162_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen"
  },
  CollectionHall_142162_Title = {
    Text = "Wohin geht die Pusteblume"
  },
  CollectionHall_142163_Desc = {
    Text = "Weite Welt, endloses Sandmeer.\nEin Ort, der nur dir und mir gehört.\nEine ewige, freie Wanderung der Liebe."
  },
  CollectionHall_142163_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen"
  },
  CollectionHall_142163_Title = {
    Text = "Wanderung durch das Sandmeer"
  },
  CollectionHall_142164_Desc = {
    Text = "Darf ich deinen Namen rufen? Selbst wenn die Welt vergeht.\"\nWenn alle Erinnerungen der Vernichtung anheimfallen, wird das pechschwarze Vergessen alles Vergangene verschlingen, das nie betrauert wurde.\nSo reichen wir uns die Hände und lassen das silberne Leuchten uns durch Verbindung vereinen.\nIn einem neuen Traum, in dem zarten Frühling, wenn die weichen Samen zu keimen beginnen."
  },
  CollectionHall_142164_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen"
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento"
  },
  CollectionHall_142165_Desc = {
    Text = "Singt laut, das strahlende LP preist die Freiheit, säet das Gynoecium der Hoffnung in alle Lande."
  },
  CollectionHall_142165_LockTip = {
    Text = "Multiversen-Link „vergessene Liebe Samen\" Abgeschlossen: Schwierig"
  },
  CollectionHall_142165_Title = {
    Text = "Eröffnungshymne"
  },
  CollectionHall_142868_Desc = {
    Text = "<Title:Einleitung>\nPontos erinnert sich noch genau an seine Gefühle an dem Tag, als er von der Geschichte seiner Familie erfuhr. Davor hatte er sich nie darauf vorbereitet, irgendeine Verantwortung zu tragen – alle mochten ihn, er war gutaussehend, witzig und sorglos.\n@1Die Schiffe, die den Königshafen das ganze Jahr über belebten, bewahrten ihn davor, sich mit dem eintönigen Alltag auseinanderzusetzen. Er hatte so viele Geschichten gehört, dass viele sagten, er sei weltgewandt – so sehr, dass er nicht zugeben wollte, ein gewöhnlicher Mensch zu sein.\nSo wurde er von einer unerwarteten und doch folgerichtigen, überwältigenden Freude erfasst. Zumal jenes mächtigere, unergründlichere Wesen hinter dem Albtraum, der seine Familie seit Generationen antrieb, ihn anerkannte – er war von Geburt an anders.\nDoch ein Scherz von „N\" ließ Fanatiker in einem wahllosen Küstenangriff das gesamte Dorf zerstören.\nUnfähig, die plötzliche Katastrophe zu ertragen, entschied sich Pontos, um die Stärke der Tiefe zu erlangen, @3 seinen Körper zu opfern – und damit alle seine Möglichkeiten.\nAber was spielte das für eine Rolle? Nichts würde mehr seiner Kontrolle entgleiten.\nEr würde nie wieder etwas verlieren."
  },
  CollectionHall_142868_LockTip = {
    Text = "Wird nach der Erweckung von „Pontos\" freigeschaltet"
  },
  CollectionHall_142868_Title = {Text = "Pontos"},
  CollectionHall_142901_Title = {
    Text = "Ebwynnos Evermore"
  },
  CollectionHall_143468_Desc = {
    Text = "Die Totenglocke hat bereits geläutet, und die Verräter bringen die wahnwitzigste Vorstellung dar.\nUnzählige Fäden — welches Ende werden sie weben?\nDu entscheidest."
  },
  CollectionHall_143468_LockTip = {
    Text = "Schließe den Ermittlungseinsatz·Schwierig Sternekapitel 5-11 ab, um freizuschalten"
  },
  CollectionHall_143468_Title = {
    Text = "Das Ende gemeinsam weben"
  },
  CollectionHall_143469_Desc = {
    Text = "Komm schnell, komm schnell, Alle warten auf Dich.\nSchreite durch den langen Korridor, betritt die ewige Bühne.\nDu bist doch der einzige Hauptdarsteller des gesamten Stücks."
  },
  CollectionHall_143469_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143469_Title = {
    Text = "Endlose Spirale"
  },
  CollectionHall_143470_Desc = {
    Text = "Sie singen gemeinsam, jeder erfüllt seine Aufgabe.\nDoch sie alle sind Sie.\nDies ist ihr niemals fallender Vorhang — ein Monolog, der ihr allein gehört."
  },
  CollectionHall_143470_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143470_Title = {
    Text = "Einzelstück"
  },
  CollectionHall_143471_Desc = {
    Text = "Act I: Spinnen\nAct II: Abwägen\nAct III: Urteilen\nSo immer wieder, so immer wieder......"
  },
  CollectionHall_143471_LockTip = {
    Text = "Schließe den Ermittlungseinsatz·Schwierig Sternekapitel 5-11 ab, um freizuschalten"
  },
  CollectionHall_143471_Title = {Text = "Drei Akte"},
  CollectionHall_143472_Desc = {
    Text = "Es war nur ein fanatischer junger Mann, der an einer gewöhnlichen Straßenecke einen Schuss abfeuerte.\nZumindest dachten Alle damals so."
  },
  CollectionHall_143472_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143472_Title = {
    Text = "[Prolog] des Kriegsfeuers"
  },
  CollectionHall_143473_Desc = {
    Text = "Knarren, knarren.\nO Schicksal, Dein Rad dreht sich ohne Rast.\nArmut und Macht lässt Du wie Eis Schmelzen.\nDu verhüllst Dich und verbirgst Dein Antlitz,\ndoch leuchtest Du mir entgegen......"
  },
  CollectionHall_143473_LockTip = {
    Text = "Schließe den Ermittlungseinsatz·Schwierig Sternekapitel 5-11 ab, um freizuschalten"
  },
  CollectionHall_143473_Title = {
    Text = "O Schicksal, wie grausam bist Du"
  },
  CollectionHall_143474_Desc = {
    Text = [[
Leb wohl, in der letzten Melodie.
Leb wohl, unter dem Blick des Schicksals.
Der Held der Geschichte wird eine neue Reise antreten.]]
  },
  CollectionHall_143474_LockTip = {
    Text = "Schließe den Ermittlungseinsatz·Schwierig Sternekapitel 5-11 ab, um freizuschalten"
  },
  CollectionHall_143474_Title = {
    Text = "Und ich singe noch immer"
  },
  CollectionHall_143475_Desc = {
    Text = "Mein Schatz, lass uns im Rausch des Weines noch einen Tanz miteinander wagen."
  },
  CollectionHall_143475_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143475_Title = {
    Text = "Angetrunkener Ball"
  },
  CollectionHall_143476_Desc = {
    Text = "Das Publikum weint beim Abschied, weint auch beim Wiedersehen.\nUnd die Gefangenen im Mittelpunkt der Bühne sollten auch einander Applaus schenken."
  },
  CollectionHall_143476_LockTip = {
    Text = "Schließe den Ermittlungseinsatz·Schwierig Sternekapitel 5-11 ab, um freizuschalten"
  },
  CollectionHall_143476_Title = {
    Text = "Der Gefangener verbeugt sich zum Abgang"
  },
  CollectionHall_143477_Desc = {
    Text = "Die Menschen neigen dazu, einen Krieg auf Der Aufschrei einer Waffe zurückzuführen.\nDoch das Schicksal lacht darüber — das ist die Selbsttäuschung der gesamten Menschheit."
  },
  CollectionHall_143477_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143477_Title = {
    Text = "Wenn der Schmetterling seine Flügel hebt"
  },
  CollectionHall_143478_Desc = {
    Text = "Eine Vorstellung ohne Nachspiel ist unvollständig.\nEin paar Zeilen geändert, das Bühnenbild angepasst, die Darsteller ausgetauscht — jede Zugabe ist ein neuer Akt."
  },
  CollectionHall_143478_LockTip = {
    Text = "Schließe den Ermittlungseinsatz·Schwierig Sternekapitel 5-11 ab, um freizuschalten"
  },
  CollectionHall_143478_Title = {
    Text = "Zugabe-Variation"
  },
  CollectionHall_143479_Desc = {
    Text = "Die Federspitze eilt über das weiße Papier, jagt den Worten nach, und die Worte führen zum längst festgelegten Ende.\nAlles geschah, bevor Du jedes Buch aufschlugst."
  },
  CollectionHall_143479_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143479_Title = {
    Text = "Was bestimmt werden wird, was bereits bestimmt ist"
  },
  CollectionHall_143480_Desc = {
    Text = "Ein Schuss Bitterstoff, 20 ml süßer Wermut, etwas Sherry, mit Eis aufgefüllt und gerührt — das ist ein vorzüglicher Aperitif und zugleich ein Stück, das fünfhundert Mal aufgeführt wurde."
  },
  CollectionHall_143480_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143480_Title = {Text = "Adonis"},
  CollectionHall_143481_Desc = {
    Text = "Wer das Schicksal als Hanswurst betrachtet, wird nicht von ihm versklavt.\nEmpfange Es mit nie endendem Gelächter, und lasst uns gemeinsam seinen Namen rufen —\nFreude."
  },
  CollectionHall_143481_LockTip = {
    Text = "Schließe den Ermittlungseinsatz·Schwierig Sternekapitel 5-11 ab, um freizuschalten"
  },
  CollectionHall_143481_Title = {
    Text = "Der Hofnarr erscheint"
  },
  CollectionHall_143482_Desc = {
    Text = "„Ich hasse Dich, hasse Dich dafür, dass Du Dich in Deinem eigenen Kokon gefangen hast, hasse Dich für Deine Hilflosigkeit, hasse Dich dafür, dass Du Dich selbst aufgegeben hast.“\n„... Doch dieser Hass verbrennt auch mich, denn ich liebe Dich auch.“"
  },
  CollectionHall_143482_LockTip = {
    Text = "Schließe den Ermittlungseinsatz·Schwierig Sternekapitel 5-11 ab, um freizuschalten"
  },
  CollectionHall_143482_Title = {
    Text = "Die Elegie des Rachegeistes"
  },
  CollectionHall_143483_Desc = {
    Text = "Die Welt bietet dir unzählige Abzweigungen, doch sie alle führen zum selben Punkt zusammen — genannt Zerstörung, genannt Ende."
  },
  CollectionHall_143483_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143483_Title = {
    Text = "Weltduplikat"
  },
  CollectionHall_143484_Desc = {
    Text = "Der Vorhang hebt und senkt sich, die Stücke wechseln, doch sie bleibt im Theater — sie ist die Dramatikerin, das Publikum und zugleich die Schauspielerin.\nO Herrin des Schicksals, du bist so grausam, ewig schweigend — und doch, warum vergießt du Tränen?"
  },
  CollectionHall_143484_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143484_Title = {
    Text = "Das schicksalhaft verwobene Spiel"
  },
  CollectionHall_143485_Desc = {
    Text = "Wenn die Zerstörung letztlich unvermeidlich ist — kann man dann erst wahre Erlösung erlangen, indem man das Netz des Schicksals zerreißt?\nNiemand kann es beantworten, kein Gott vermag es zu beantworten.\nDoch zumindest wird auch das grenzenlose Leid gemeinsam vergehen."
  },
  CollectionHall_143485_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143485_Title = {
    Text = "Gotteslästerliche Vorstellung"
  },
  CollectionHall_143486_Desc = {
    Text = "Jene Gesichter, die durch die Welt wandeln, so ungemein wahr und scheinbar frei — sie sind nichts weiter als feste Requisiten auf einer Bühne.\nJede Bewegung, jede Geste wird von den Fäden des Schicksals gelenkt."
  },
  CollectionHall_143486_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143486_Title = {
    Text = "Der Faden aller Wesen"
  },
  CollectionHall_143487_Desc = {
    Text = "Nach dem Erwachen wird alles verschwinden, vollständig der Vergessenheit anheimfallen — das Anwesen, der Blumengarten, die Lieder, die Gemälde......\nDas war ein Frühling, der niemals existiert hat."
  },
  CollectionHall_143487_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143487_Title = {
    Text = "Der Traumweben des Frühlings"
  },
  CollectionHall_143488_Desc = {
    Text = "Die Streicher setzen sanft ein, die Zofe singt.\nDie Person hinter den Kulissen tritt ins Rampenlicht, verbeugt sich vor dir und lädt dich ein, Zeuge dieser vorherbestimmten Schicksalsbahn zu werden."
  },
  CollectionHall_143488_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143488_Title = {
    Text = "Ihren Schleier lüften"
  },
  CollectionHall_143489_Desc = {
    Text = "Dies ist ein Improvisationstanz, der nur einmal im Leben aufgeführt werden kann.\nDoch das macht nichts — er wird das Glück haben, als Präparation zu dienen und für immer festgehalten zu werden."
  },
  CollectionHall_143489_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143489_Title = {
    Text = "Tanzstück: „Der Tod des Schwans\""
  },
  CollectionHall_143490_Desc = {
    Text = "Der Vorhang öffnet sich, absurde Figuren betreten nacheinander die Bühne.\nSie singen, sie tanzen, und bevor das Schicksal hereinbricht, bringen sie beharrlich ihr Stück auf die Bühne — auch wenn das Ende längst geschrieben ist."
  },
  CollectionHall_143490_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143490_Title = {
    Text = "Duett zum Vorhangaufzug"
  },
  CollectionHall_143491_Desc = {
    Text = "Damit alles auf dem richtigen Weg bleibt, muss stets etwas ausgesondert, verworfen werden.\nDie nicht auserwählten Existenzen stürzen allesamt in den pechschwarzen Abgrund — ihr Jammern und Schimpfen wird am Ende von niemandem gehört."
  },
  CollectionHall_143491_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143491_Title = {
    Text = "Das verlassene „Ich\""
  },
  CollectionHall_143492_Desc = {
    Text = "So zu sterben ist wirklich schön. Das dachte Sie."
  },
  CollectionHall_143492_LockTip = {
    Text = "Schließe den Ermittlungseinsatz Sternekapitel 5-16 ab, um freizuschalten"
  },
  CollectionHall_143492_Title = {
    Text = "Die schönste Sühne"
  },
  CollectionHall_143592_LockTip = {
    Text = "Schließe ein beliebiges Level in der Bewusstseinsdrift „Ebwynnos Evermore\" ab, um es freizuschalten"
  },
  CollectionHall_143592_Title = {Text = "Sucht"},
  CollectionHall_144377_Desc = {
    Text = "In den langen Äonen ihrer Wacht betrat Tawil einst ein Sterblichenreich.\nUnsichtbar wandelte sie an den Rändern der sterblichen Welt und beobachtete still das Treiben aller Lebewesen.\n\nAn einem gewöhnlichen Abend fiel ihr ein dichtes Lichtermeer am Stadtrand ins Auge.\nBühnenkulissen, Gesang und Tanz, Händler, die Gebäck ausriefen, spielende Kinder, Müßiggänger, die fröhlich die Becher hoben. Es war der Atem des Lebens selbst, ein flüchtiger Moment der Ruhe.\nVerzaubert konnte sie nicht umhin, Sterblichengestalt anzunehmen.\n\n„Guten Tag. Ein Zuckerbild, bitte.\"\n„Sofort, junge Dame. Was soll ich für Sie zeichnen?\"\nTawil neigte sanft den Kopf. Sie dachte nur daran, die herrenlosen Münzen anzubieten, die sie zufällig gefunden hatte, und vergaß dabei völlig, dass sie sich auch einen eigenen Wunsch hätte äußern können.\n„Wenn Sie sich nicht entscheiden können, soll ich vielleicht eines nach Ihrem Ebenbild zeichnen? Sie sind schön wie eine Göttin.\"\nTawil lächelte und nickte. Der Händler rief fröhlich etwas, hob eine Kelle mit geschmolzenem Zucker und begann zu malen.\n\n<Italic:Tropf. Tropf.>\nWas auf die Steinplatte fiel, war kein honigfarbener Sirup.\nSondern Regen – schwarzer Regen.\nSchwarzes Serum tropfte aus unergründlicher Höhe herab und schmolz einen entsetzlichen Riss quer durch den Himmel.\n\nDann begann Tawil nach oben zu fallen.\nEs war die Welt, die versank. Das Lächeln des Händlers erstarrte in ihrer Erinnerung und ertrank dann zusammen mit allem anderen im schwarzen Ozean. Alles wurde zu einem bloßen Fleck unter zahllosen toten Sternen, der in einer Vergangenheit verschwand, die für immer außer ihrer Reichweite lag.\nDies war der Aufruhr, den sie verursacht hatte, und die Vergeltung, die sie tragen sollte.\nSie blickte in die Ferne, still und reglos. Sie fiel einfach weiter nach oben.\nDenn dies war der Ort, den sie bewachen sollte – das Silbertor, das „Zeit und Raum transzendiert\".\nHier würde sie Wacht halten, für alle Ewigkeit."
  },
  CollectionHall_144377_Title = {
    Text = "Aufstieg in den Abgrund"
  },
  CollectionHall_144448_Desc = {
    Text = "Dir wurde eine unerreichbare Utopie versprochen, in der all die lieben alten Seelen aus deiner Erinnerung wohnen."
  },
  CollectionHall_144448_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Ebwynnos Evermore\" ab"
