  CollectionHall_144449_Title = {
    Text = "Narben des Kenotaphs"
  },
  CollectionHall_144450_Desc = {
    Text = "Die Sonne ist unter die Flut gesunken, der letzte Lichtfaden hinter ihm verschleiert.\nDämmerung und Morgenröte werden im nächsten Atemzug die Plätze tauschen, und er wird alle Dinge hier so bewahren, wie sie sind."
  },
  CollectionHall_144450_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Ebwynnos Evermore\" auf Schwierig ab"
  },
  CollectionHall_144450_Title = {
    Text = "Die sinkende Sonne"
  },
  CollectionHall_144451_Desc = {
    Text = "Der Mond kichert, der Mond flüstert.\nSchicksal, oh Schicksal, sagt der Mond – das Schicksal ist im Begriff zu fallen."
  },
  CollectionHall_144451_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Ebwynnos Evermore\" ab"
  },
  CollectionHall_144451_Title = {
    Text = "Der fallende Mond"
  },
  CollectionHall_144452_Desc = {
    Text = "Unwissentlich hatte er Menschen dazu gebracht, etwas bei ihm zu lassen.\nUnwissentlich ließ er selbst etwas zurück, genau wie sie."
  },
  CollectionHall_144452_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Ebwynnos Evermore\" ab"
  },
  CollectionHall_144452_Title = {Text = "Ihr Eros"},
  CollectionHall_144453_Desc = {
    Text = "Für den Schwarm bedeutet es, das Meer zu verlassen, nichts als Erstickung zu kennen."
  },
  CollectionHall_144453_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Ebwynnos Evermore\" auf Schwierig ab"
  },
  CollectionHall_144453_Title = {
    Text = "Gefangen im Meer"
  },
  CollectionHall_144454_Desc = {
    Text = "Töricht, oberflächlich, eitel, einsam – der brüchige Despot hat sich ein eigenes Königreich geschmiedet.\nUnveränderliche Hüllen atmen keine Wahrheit; denn nichts kann aus der Schlucht ein Herz zusammenfügen, das zu sehr den Wandel fürchtete – und so vor seiner Zeit zerbrach."
  },
  CollectionHall_144454_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Ebwynnos Evermore\" ab"
  },
  CollectionHall_144454_Title = {
    Text = "Der endlose Triumph"
  },
  CollectionHall_144476_Desc = {
    Text = "Möge dieser flüchtige Tanz im Strom der Zeit ewig werden.\nIn der Nacht des nächsten Jahreswechsel Fests werden wir uns im Mondlicht wiedersehen.\n*<Italic:Vater und Tochter... wie rührend>. (ノへ￣、)"
  },
  CollectionHall_144476_LockTip = {
    Text = "Abschluss des Sondereinsatzprotokolls „Der Zug zum Qisui-Festival\""
  },
  CollectionHall_144476_Title = {
    Text = "Jahreswechsel Fest Feuerwerk"
  },
  CollectionHall_145434_LockTip = {
    Text = "Abschluss eines beliebigen Levels der zeitbegrenzten Aktion „Vorübergehender Text\""
  },
  CollectionHall_145434_Title = {
    Text = "Temporärer Text"
  },
  CollectionHall_145460_Desc = {
    Text = "Seit dem Tag seiner Geburt war es in ewigem Hunger gefangen.\nDie Kadaver von Sternen zerbrachen zwischen seinen Zähnen; die Trümmer von Zivilisationen verfaulten in seinem Bauch. Sein Hunger war ein Fluch, älter als die Zeit selbst. Immer wieder verschlang es Macht und trieb seine Sklaven durch endlose Spiele aus Macht und Begehren – doch nie verstand es, was seine eigene Existenz bedeutete.\nBis die Kriegerin namens Lotan vor ihm erschien.\n„Leviathan.\"\nEs konnte sich nicht erinnern, wann sein Name zuletzt ausgesprochen worden war. Kniende Könige wagten es nicht, ihn zu nennen; wahnsinnige Priester konnten ihn nur in Hymnen verhüllen.\nDoch sie sprach ihn mühelos aus – als würde sie einen lang ersehnten Rivalen begrüßen.\n„Du bist dran.\"\nEs hatte zwölftausend Jahre existiert. In dieser gewaltigen Ewigkeit waren Planeten seine Nahrung, Lebewesen bloße Ameisen und selbst die mächtigsten Krieger kaum mehr als flüchtige Zeitvertreibe. Nichts hatte es je gesättigt. Nichts hatte es je erschreckt.\nBis heute.\nDiese Sterbliche, diese Kriegerin, hob ihr Großschwert und schlug wie ein Sturm zu.\nDie Klinge riss durch seine Schuppen. In seinen Ohren hallte das Brüllen seiner Geburt aus dem Chaos. Sein Zorn zerspaltete Himmelskörper; sein Hunger verschluckte Nebel im Ganzen.\nDie Klinge trennte seine Klauen ab. Es erinnerte sich – an die Göttin im weißen Schleier, die vor ihm erschienen war und seine Macht von seinem Willen gerissen hatte.\nUnd in dem Augenblick, als die Klinge sein Herz durchbohrte, lachte Leviathan.\nZwölf Jahrtausende. Sein verlorener Wille war endlich zu ihm zurückgekehrt – um es zu zerschmettern, zu bezwingen und zu verschlingen. Nun würde sie es vorwärtsführen, durch alle Reiche und in die fernsten Weiten des Kosmos, um jede Macht zu bezwingen, die es wagte, sich ihnen entgegenzustellen.\nAn jenem Tag wurde die uralte Chaosbestie wiedergeboren. In dem Augenblick, als es zu ihr zurückkehrte, verstand es endlich: Beide waren aus ein und demselben geboren – reiner, absoluter Stärke.\nStärke selbst war die einzige Bedeutung, die es je gegeben hatte."
  },
  CollectionHall_145460_Title = {
    Text = "Himmlischer Untergang"
  },
  CollectionHall_146400_Desc = {
    Text = "Unfähig, die urzeitliche Wut des Astralen Cetus zu bändigen, trennte die alte Gottheit Ihren Geist von Ihrem Fleisch. So fiel Ihr Wille auf das karge Land und inkarnierte als eine Kriegerin namens Lotan: Cetarchon.\nVon kriegerischer Natur betrachtete sie das Streben nach ultimativer Stärke als ihren einzigen Instinkt und ihre einzige Ehre. Sie trat in die Prüfung des Astralen Cetus ein und schloss einen Pakt mit Ihm. Dann, auf dem Höhepunkt ihrer Macht, streckte sie ihren eigenen Meister mit ihrem Großschwert nieder und machte die Kraft des sternverschlingenden Ungeheuers zu ihrer eigenen.\nScharfe Walknochen durchbohrten ihr Fleisch; dunkle Knochenpanzer umhüllten ihre Gestalt. Jene Augen, die einst den Kosmos in sich trugen, spiegeln nun nichts als kalte Prüfung ihrer Feinde wider.\nSie empfindet keine Freude an der Zerstörung, noch lässt sie sich dazu herab, an sinnlosem Gemetzel teilzunehmen. Sie begehrt nichts als noch aufregendere Gegner und immer größere Stärke.\nDie reinste Kriegerin jagt die Schatten der Mächtigen durch den Sternenkosmos – bis sie alle unter ihrer Klinge fallen und jeder Weg bis zu seinem äußersten Ende beschritten wurde."
  },
  CollectionHall_146400_LockTip = {
    Text = "Bewusstseinsdrift abgeschlossen: „Bis der Cetus fällt\""
  },
  CollectionHall_146400_Title = {
    Text = "Lotan: Cetarchon"
  },
  CollectionHall_146412_Title = {
    Text = "Bis der Cetus fällt"
  },
  CollectionHall_146867_LockTip = {
    Text = "Abschluss eines beliebigen Levels der zeitbegrenzten Aktion „Vorübergehender Text\""
  },
  CollectionHall_146867_Title = {
    Text = "Temporärer Text"
  },
  CollectionHall_147491_LockTip = {
    Text = "Abschluss eines beliebigen Levels der zeitbegrenzten Aktion „Vorübergehender Text\""
  },
  CollectionHall_147491_Title = {
    Text = "Temporärer Text"
  },
  CollectionHall_147860_Desc = {
    Text = "In den verborgenen Winkeln von Lentinis Hintergassen lebt eine Geschichte, die jeder gehört hat und die von Mund zu Mund weitergegeben wird.\n\nSie wird niemals unter den zitternden Federfächern und Spitzenfächern der Damen beim Nachmittagstee auftauchen, noch wird sie beiläufig von Herren erwähnt, die sich nach dem Abendessen mit seidenen Taschentüchern den Mund abtupfen. Nur Hexen, die die obskursten und ältesten Beschwörungen rezitieren, oder Kundschafter, die die seltsamsten und verschlungensten Aufträge übernehmen, haben die geringste Chance, dieses Geheimnis zu erfahren.\n\nHm? Sie fragen, warum dann jeder davon wissen sollte? Ah, aber das ist gerade der Schlüssel zur ganzen Geschichte! Jede Seele, die daran teilgenommen und die Geschichte weiterverbreitet hat, ist so überaus großartig, so überaus gütig. Kein einziges Körnchen selbstsüchtigen Verlangens liegt in Ihren Herzen, und wenn doch eines gefunden werden sollte, wäre es gewiss nur der Wunsch, dass jeder Mensch, der in dieser Welt ums Überleben kämpft, wahrhaftig von seinem Leid erlöst werden und in das schneeweise Land des Makellosen und Reinen zurückkehren möge. Alles in dieser Welt entsprang einem roten, duftenden Apfel, einem Apfel so verführerisch, dass jeder, der ihn erblickte, danach verlangte, hineinzubeißen.\n\nSein Saft ist so reichlich, dass ein einziger Biss jeden rastlosen Hunger stillen kann. Sein Duft ist so intensiv, dass ein einziger Atemzug davon jeden unausgesprochenen Kummer vertreiben kann. Im Gewand eines gewöhnlichen Apfels versteckt er sich unter all den anderen Äpfeln und hält Aufzeichnung über jedes Gute und jedes Böse, über jede Ursache und jede Folge. Jeder Mythos und jede Legende, die je einen Apfel erwähnte, ist nur eine Seite aus der Chronik seiner früheren Herrlichkeiten.\n\nAm allerwichtigsten ist, dass er, weil er so selbstlos und so gleich in seiner Liebe ist, der Glaubensgemeinschaft, die ihn verehrt, keinerlei Taufe bedarf. Man erinnere sich nur an einen der Grundsätze der Kirche des Apfels: Ein wahrer Gott kümmert sich nicht um bloße Formalitäten! Wenn Sie zum ersten Mal den Namen der Kirche des Apfels hören, wenn zum ersten Mal ein praller, rubinroter, verlockender Apfel in Ihrem Geist Gestalt annimmt, müssen Sie nur daran glauben, und Sie sind bereits ein Mitglied der Kirche.\n\nSie streitet mit keinem anderen Glauben. Ein wahrer Gott heißt jedes Kind willkommen, das bereit ist, ihn zu umarmen. Solange Sie einen kleinen Winkel in Ihrem Herzen für die Kirche des Apfels freihalten, wird der Apfelhimmel Sie nach Ihrer Rückkehr in den ewigen Frieden – sollten die Lehren, denen Sie zuvor gefolgt sind, keine Wirkung zeigen und Sie sich außerstande sehen, in jene gesegneten Lande einzutreten, die in ihren Lehren versprochen werden – ohne das geringste Zögern aufnehmen, und die Bleiche Fee, die ihn seit unvordenklichen Zeiten begleitet, wird Sie in jene ewige, süße Behausung voller Apfelduft geleiten.\n\n„Nun werden all diese frohen Botschaften kostenlos verbreitet. Für nur einen einzigen Leonian Florin können Sie sich einen völlig unverbindlichen Notfallplan sichern, zusammen mit einem Apfel, der möglicherweise genau der Apfel ist, den die Kirche des Apfels verehrt. <Italic:*Jeder Apfel in dieser Welt kann jener Apfel sein, und da die White Fee derzeit in seinem Namen handelt, ist die Wahrscheinlichkeit etwas höher. Kurz gesagt: Bitte essen Sie mehr Äpfel.“> ...\n\n„Mein Gott, wir haben Caraboos Taschengeld nur für eine einzige kleine Woche gekürzt, und nur weil sie es mit ihrem Schmeicheln und Schwindeln ein wenig zu weit getrieben hatte!“ „Und das ist es, was dieser kleine Kopf von ihr als Nächstes ausgeheckt hat?!“"
  },
  CollectionHall_147860_Title = {
    Text = "Honigsüße Täuschung"
  },
  CollectionHall_147986_Desc = {
    Text = "Ein Seil soll seine Zunge binden, eine Schnur soll durch seine Nase gezogen werden, und ein Haken soll seinen Kiefer durchbohren.\nUnd so fällt der stolze König, und so fällt auch der Himmel."
  },
  CollectionHall_147986_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Bis der Cetus fällt\" ab"
  },
  CollectionHall_147986_Title = {
    Text = "Leviathans Sterbelied"
  },
  CollectionHall_147987_Desc = {
    Text = "Auf der trostlosen Einöde streifen glühende Bestien umher.\nJede wartet auf den Moment, ihre Reißzähne tief in die Kehle zu schlagen und die andere in Stücke zu reißen."
  },
  CollectionHall_147987_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Bis der Cetus fällt\" ab"
  },
  CollectionHall_147987_Title = {
    Text = "Entblößte Reißzähne"
  },
  CollectionHall_147988_Desc = {
    Text = "Leg deine langweilige Krone ab; ich habe ihr keinen zweiten Blick gegönnt. Zieh deine Klinge – die Welt ist wahnsinnig nach Blut!\nDafür, und nur dafür –\nErschlage! Verschlinge! Vergeh!"
  },
  CollectionHall_147988_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Bis der Cetus fällt\" ab"
  },
  CollectionHall_147988_Title = {
    Text = "Sternenerschlagende Raserei"
  },
  CollectionHall_147989_Desc = {
    Text = "Als ich noch der niedrigste aller Diener war, wurde ich einst Zeuge eines Feldzugs von schonungsloser Grausamkeit.\nJene legendäre Meisterin – Macht hatte ihr Fleisch und ihre Knochen geformt, ihr brodelndes Blut wurde zu einer unsterblichen Flamme, und dieses Feuerlicht entzündete wiederum ihre Augen –\nBewahre diese Erinnerung für mich, mein Kind ... Am Ende triumphierte sie und eroberte das Sternenmeer."
  },
  CollectionHall_147989_LockTip = {
    Text = "Schließe die Bewusstseinsdrift „Bis der Cetus fällt\" ab"
  },
  CollectionHall_147989_Title = {
    Text = "Eroberung kennt keine Ruhe"
