  CollectionHall_48635_Desc = {
    Text = "<Title:Profile>\nInterimsdekan von Mythag.\nAusgebildet unter Crowley McKinnon, einem direkten Junior von Herbert.\nEiner der Zeugen von Herberts Mord an ihrem Mentor, hat sie seit dem Tod des Mentors die Geschäfte der Akademie geleitet.\nEine absolute Effizienzwahnsinnige, sie ist nie zu spät und hält ihr Haar kurz, um Zeit beim Frisieren zu sparen.\nKam aus ihrem kriegszerrissenen Heimatland Elche nach Leo geflohen.\nIhr rechter Zeigefinger kann sich nicht richtig biegen, angeblich aufgrund brutaler Behandlung in einem Konzentrationslager."
  },
