  CollectionHall_48636_Desc = {
    Text = "<Title:Einführung>\nEiner der drei Gründer, neben Ward Phillips und Kralarques, gründete die Vorgängerin der Mythag-Universität—das Mythag-College.\nSie ist die erste \"Erweckerin\" und die Quelle der Erweckertechnologie.\nSie bewacht den Schwarzen Pool seit vielen Jahren, sehr wenige Menschen haben ihr Gesicht gesehen, was sie zu einem der höchsten Geheimnisse der Mythag-Universität macht.\n\"Shh... frag nicht nach deinem @2.\""
