  CollectionHall_51019_Desc = {
    Text = "<Title:Gründungsdatum>\nVor der Großen Flut\n\n<Title:Gründer>\nUnbekannt\n\n<Title:Übersicht>\nEin nomadisches Volk, das sich vom Assyrischen Reich abgespalten hat.\nVersteckt inmitten der heftigen Stürme der Lemwash-Wüste leben sie auf sehr primitive Weise und kommunizieren selten mit Außenstehenden. Das Aram-Volk verehrt den \"Mutterbaum des Überflusses\" und verlässt sich auf dessen außergewöhnliche Fortpflanzungsfähigkeiten sowie das heilige Flusswasser, um ihre Bevölkerungszahl aufrechtzuerhalten.\nNach dem \"Lemwash-Zwischenfall\" verschwand das Aram-Volk spurlos, ohne weitere Nachrichten."
  },
