  CollectionHall_51374_Desc = {
    Text = "<Title:Profil>\nProfessor an der Mythag Universität, sozialer Aktivist und Adliger.\nEinst ein wohlhabender Playboy, der an harmlosen Verbrechen beteiligt war, berühmt sowohl im Untergrund als auch in der Gesellschaft.\nÜberlebte ein Familienschlachten durch Kultisten. Seitdem weiß nur er, was wirklich geschehen ist.\nPflegevater von Ramona, spricht jedoch nicht über ihre Herkunft.\nVersagte in seiner Jugend in allen Fächern, wurde später Professor an der Mythag Universität.\nBekannt für seinen extravaganten Lebensstil, doch romantische Gerüchte über ihn sind nie aufgetaucht.\nIm Wesentlichen ein Mann voller Widersprüche."
  },
  CollectionHall_51374_LockTip = {
    Text = "Wird nach dem Abschluss des Prologs freigeschaltet"
  },
  CollectionHall_51374_Title = {Text = "Dexter"},
  CollectionHall_51375_Desc = {
    Text = "<Title:Introduction>\nDexters Adoptivtochter und der vertrauenswürdigste Ermittlungsbegleiter des Hauptcharakters.\nNachdem sie in verschiedenen Abteilungen der Akademie aufgewachsen ist, verfügt sie über ein erhebliches Verständnis des D-Phänomens, der Erwachter und anderer verwandter Kenntnisse.\n\nIn jungen Jahren sehnte sich Ramona einmal nach ihren \"biologischen Eltern.\" Doch dank der Fürsorge und Liebe von Dexter und ihren Lehrern betrachtet sie die Akademie längst als ihr wahres Zuhause.\n\nRuhig, rational und angemessen freundlich, zeigt sie keinerlei Anzeichen von \"Seltsamkeit\" — unter den exzentrischen Menschen von Mythag sticht ihre \"Normalität\" deutlich hervor.\nObwohl sie oft einen kalten Ausdruck trägt, verstehen diejenigen, die sie gut kennen, dass es sich lediglich um die Ermüdung eines \"Genies\" handelt"
  },
