  CollectionHall_65509_Desc = {
    Text = "<Title:Einführung>\nEin kleiner Auftragskiller aus dem östlichen Bezirk und die Schwester von \"24.\" \nSie hat drei einzigartige Fähigkeiten: Kleptomanie, Streiten und Wegrennen, wenn die Dinge schiefgehen.\nNiemand erhält auch nur den geringsten Vorteil von ihr.\nOh, und sie hat eine kleine Maus namens \"Braun\", die sie oft begleitet.\nBraun ist reif und ausgeglichen und ergänzt Jenkin's Persönlichkeit gut.\nSo hat Jenkin, obwohl es in Ost-Londinium häufig Vorfälle gibt, bei denen hungernde Menschen Mäuse kochen, niemals solche Gedanken gehegt."
  },
