  CollectionHall_89374_Desc = {
    Text = "Das Urteil wird nicht aufhören; das Urteil muss vollstreckt werden.\nMonster werden aus dem Spiegel geboren, mit ihrem eigenen Fleisch und Blut als Docht und verbreiten das Feuer der Reinigung in der ganzen Welt."
