  CollectionHall_89375_Desc = {
    Text = "Wenn Positionen und Willen kollidieren, glauben Menschen oft nur an ihre eigenen Prinzipien.\nFür die meisten Menschen ist das, woran sie glauben, die einzige Gerechtigkeit."
