  },
  CollectionHall_89407_Desc = {
    Text = "In diesem dichten Nebel, wo die Sonne nicht sichtbar ist, werde ich allein in das Unbekannte vor mir schreiten. \nIch werde Staub, Blut und Feuer aus diesem Nebel sammeln und die einsamen, verwirrten und traurigen Tränen beruhigen. \nIch werde mich nicht mehr fürchten, denn die ewige Sonne hängt längst hoch in meinem Herzen."
