  },
  CollectionHall_89414_Desc = {
    Text = "Helden und die Prinzessin rennen unter dem Nachthimmel, der Kies unter ihren Füßen erzählt die Freude des Lebens. Dieses Herz, tausend Jahre versiegelt, beginnt langsam zu schlagen mit dem Durchgang eines Sterns."
