  CollectionHall_89415_Desc = {
    Text = "Keine Worte nötig, wenn du hierher kommst, wirst du die aufrichtigste Hilfe erhalten. \nDie lächelnde Führerin hat dir ihre Hand gereicht; sie wird dich in die Tiefen des Waldes deiner Seele führen, den du noch nie klar gesehen hast."
